 m=json.loads((R/'deletion_manifest.json').read_text());v=json.loads((R/'verification.json').read_text());receipt=json.loads((R/'deletion_receipt_final.json').read_text());cmds=json.loads((R/'execution_commands.json').read_text());inv=json.loads((R/'inventory.json').read_text());plan=json.loads((R/'protection_plan.json').read_text());b=json.loads((R/'df_before.json').read_text());a=json.loads((R/'df_after.json').read_text());ctx=json.loads((R/'context.json').read_text())
 pre_scan=json.loads((R/'proc_scan_pre.json').read_text());immediate_scan=json.loads((R/'proc_scan_immediate.json').read_text())
 cats=defaultdict(lambda:dict(entries=0,dirs=0,files=0,bytes=0));total=dict(entries=0,dirs=0,files=0,bytes=0)
